import { PushNotifications } from '@capacitor/push-notifications';

/**
 * Wires up the @capacitor/push-notifications runtime for Android FCM (HTTP v1).
 *
 * Order matters (per the plugin docs):
 *   1. Register listeners for every event the app cares about.
 *   2. Ask the OS for permission via `requestPermissions()`.
 *   3. Only when the returned `receive` value is `'granted'`, call `register()`.
 */
export function initPush(): void {
  // 1. Listeners -------------------------------------------------------------
  PushNotifications.addListener('registration', (token) => {
    // TODO: forward `token.value` to your backend so it can target this device.
    console.info('[push] FCM registration token:', token.value);
  });

  PushNotifications.addListener('registrationError', (error) => {
    console.error('[push] FCM registration failed:', JSON.stringify(error));
  });

  PushNotifications.addListener(
    'pushNotificationReceived',
    (notification) => {
      // App is in the foreground — show an in-app banner/toast.
      console.info(
        '[push] Notification received in foreground:',
        JSON.stringify(notification)
      );
    }
  );

  PushNotifications.addListener(
    'pushNotificationActionPerformed',
    (action) => {
      // User tapped the system notification — deep-link as needed.
      console.info(
        '[push] Notification action performed:',
        JSON.stringify(action)
      );
    }
  );

  // 2. Permission gate -------------------------------------------------------
  PushNotifications.requestPermissions().then((result) => {
    // 3. Register only when permission has been granted.
    if (result.receive === 'granted') {
      PushNotifications.register();
    } else {
      console.warn(
        '[push] Notification permission not granted; skipping register().'
      );
    }
  });
}

import type { PermissionState, PluginListenerHandle } from '@capacitor/core';
export type PresentationOption = 'badge' | 'sound' | 'alert' | 'banner' | 'list';
declare module '@capacitor/cli' {
    interface PluginsConfig {
        /**
         * You can configure the way the push notifications are displayed when the app is in foreground.
         */
        PushNotifications?: {
            /**
             * This is an array of strings you can combine. Possible values in the array are:
             *   - `badge`: badge count on the app icon is updated (default value)
             *   - `sound`: the device will ring/vibrate when the push notification is received
             *   - `alert`: **Deprecated on iOS.** Use `banner` and `list` instead. On Android, this value is still used to display the notification.
             *   - `banner`: the push notification is displayed as a banner. On Android, defaults to the same behavior as `alert`.
             *   - `list`: the push notification is displayed in the notification center. On Android, defaults to the same behavior as `alert`.
             *
             * An empty array can be provided if none of the options are desired.
             *
             * badge is only available for iOS.
             *
             * @since 1.0.0
             * @example ["badge", "sound", "alert", "banner", "list"]
             */
            presentationOptions: PresentationOption[];
        };
    }
}
export interface PushNotificationsPlugin {
    /**
     * Register the app to receive push notifications.
     *
     * This method will trigger the `'registration'` event with the push token or
     * `'registrationError'` if there was a problem. It does not prompt the user for
     * notification permissions, use `requestPermissions()` first.
     *
     * @since 1.0.0
     */
    register(): Promise<void>;
    /**
     * Unregister the app from push notifications.
     *
     * This will delete a firebase token on Android, and unregister APNS on iOS.
     *
     * @since 5.0.0
     */
    unregister(): Promise<void>;
    /**
     * Get a list of notifications that are visible on the notifications screen.
     *
     * @since 1.0.0
     */
    getDeliveredNotifications(): Promise<DeliveredNotifications>;
    /**
     * Remove the specified notifications from the notifications screen.
     *
     * @since 1.0.0
     */
    removeDeliveredNotifications(delivered: DeliveredNotifications): Promise<void>;
    /**
     * Remove all the notifications from the notifications screen.
     *
     * @since 1.0.0
     */
    removeAllDeliveredNotifications(): Promise<void>;
    /**
     * Create a notification channel.
     *
     * Only available on Android O or newer (SDK 26+).
     *
     * @since 1.0.0
     */
    createChannel(channel: Channel): Promise<void>;
    /**
     * Delete a notification channel.
     *
     * Only available on Android O or newer (SDK 26+).
     *
     * @since 1.0.0
     */
    deleteChannel(args: {
        id: string;
    }): Promise<void>;
    /**
     * List the available notification channels.
     *
     * Only available on Android O or newer (SDK 26+).
     *
     * @since 1.0.0
     */
    listChannels(): Promise<ListChannelsResult>;
    /**
     * Check permission to receive push notifications.
     *
     * On Android 12 and below the status is always granted because you can always
     * receive push notifications. If you need to check if the user allows
     * to display notifications, use local-notifications plugin.
     *
     * @since 1.0.0
     */
    checkPermissions(): Promise<PermissionStatus>;
    /**
     * Request permission to receive push notifications.
     *
     * On Android 12 and below it doesn't prompt for permission because you can always
     * receive push notifications.
     *
     * On iOS, the first time you use the function, it will prompt the user
     * for push notification permission and return granted or denied based
     * on the user selection. On following calls it will get the current status of
     * the permission without prompting again.
     *
     * @since 1.0.0
     */
    requestPermissions(): Promise<PermissionStatus>;
    /**
     * Called when the push notification registration finishes without problems.
     *
     * Provides the push notification token.
     *
     * @since 1.0.0
     */
    addListener(eventName: 'registration', listenerFunc: (token: Token) => void): Promise<PluginListenerHandle>;
    /**
     * Called when the push notification registration finished with problems.
     *
     * Provides an error with the registration problem.
     *
     * @since 1.0.0
     */
    addListener(eventName: 'registrationError', listenerFunc: (error: RegistrationError) => void): Promise<PluginListenerHandle>;
    /**
     * Called when the device receives a push notification.
     *
     * @since 1.0.0
     */
    addListener(eventName: 'pushNotificationReceived', listenerFunc: (notification: PushNotificationSchema) => void): Promise<PluginListenerHandle>;
    /**
     * Called when an action is performed on a push notification.
     *
     * @since 1.0.0
     */
    addListener(eventName: 'pushNotificationActionPerformed', listenerFunc: (notification: ActionPerformed) => void): Promise<PluginListenerHandle>;
    /**
     * Remove all native listeners for this plugin.
     *
     * @since 1.0.0
     */
    removeAllListeners(): Promise<void>;
}
export interface PushNotificationSchema {
    /**
     * The notification title.
     *
     * @since 1.0.0
     */
    title?: string;
    /**
     * The notification subtitle.
     *
     * @since 1.0.0
     */
    subtitle?: string;
    /**
     * The main text payload for the notification.
     *
     * @since 1.0.0
     */
    body?: string;
    /**
     * The notification identifier.
     *
     * @since 1.0.0
     */
    id: string;
    /**
     * The notification tag.
     *
     * Only available on Android (from push notifications).
     *
     * @since 4.0.0
     */
    tag?: string;
    /**
     * The number to display for the app icon badge.
     *
     * @since 1.0.0
     */
    badge?: number;
    /**
     * It's not being returned.
     *
     * @deprecated will be removed in next major version.
     * @since 1.0.0
     */
